"""Typed peer enrollment and source/central receipts; no startup migrations."""
MUTABLE={
    'CX_MODEL_COORD_BINDINGS':{'STATUS','VERSION'},
    'CX_MODEL_COORD_ROUTES':{'STATUS','VERSION'},
    'CX_MODEL_ORIGIN_RECEIPTS':{'STATUS','VERSION','COORDINATOR_REQUEST_ID','ADMISSION_ID','REMOTE_FENCING_TOKEN',
        'REMOTE_RESERVATION_VERSION','AUTHORIZED_AT_MS','PROOF_EXPIRES_AT_MS','PROOF_DIGEST','FINISH_CODE'},
    'CX_MODEL_COORD_REQUESTS':{'STATUS','VERSION','ADMISSION_ID','PROOF_DIGEST','PROOF_EXPIRES_AT_MS','FINISH_CODE'},
}


def schema_statements(dialect):
    if dialect not in {'pg','postgresql','oracle','yashandb'}:raise ValueError('Unsupported database adapter')
    integer='DECIMAL(19,0)' if dialect in {'pg','postgresql'} else 'NUMBER(19)'
    statements=[
        "CREATE TABLE CX_MODEL_COORD_BINDINGS (BINDING_ID VARCHAR(128) PRIMARY KEY, GROUP_ID VARCHAR(128) NOT NULL, "
        "ORIGIN_ID VARCHAR(128) NOT NULL, INSTALLATION_KEY VARCHAR(128) NOT NULL, "
        "CREDENTIAL_ID VARCHAR(128) NOT NULL REFERENCES CX_MODEL_GATEWAY_CREDENTIALS(CREDENTIAL_ID), "
        "PROFILE_ID VARCHAR(128) NOT NULL REFERENCES CX_LLM_PROVIDER_PROFILES(PROFILE_ID), PROFILE_VERSION INTEGER NOT NULL CHECK(PROFILE_VERSION>0), "
        "ORIGIN_PROFILE_ID VARCHAR(128) NOT NULL, ORIGIN_PROFILE_VERSION INTEGER NOT NULL CHECK(ORIGIN_PROFILE_VERSION>0), "
        "POLICY_REVISION INTEGER NOT NULL CHECK(POLICY_REVISION>0), STATUS VARCHAR(16) NOT NULL CHECK(STATUS IN ('ACTIVE','REVOKED')), "
        "VERSION INTEGER DEFAULT 1 NOT NULL CHECK(VERSION>0), REGISTERED_BY VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), "
        "IDEMPOTENCY_KEY VARCHAR(128) NOT NULL, REQUEST_DIGEST VARCHAR(64) NOT NULL, CREATED_AT_MS BIGINT_VALUE NOT NULL, "
        "UNIQUE(REGISTERED_BY,IDEMPOTENCY_KEY), FOREIGN KEY(GROUP_ID,ORIGIN_ID) REFERENCES CX_MODEL_CAP_ORIGINS(GROUP_ID,ORIGIN_ID), "
        "FOREIGN KEY(GROUP_ID,POLICY_REVISION) REFERENCES CX_MODEL_CAP_REVISIONS(GROUP_ID,REVISION_NO))",
        "CREATE TABLE CX_MODEL_COORD_ROUTES (ROUTE_ID VARCHAR(128) PRIMARY KEY, "
        "PROFILE_ID VARCHAR(128) NOT NULL REFERENCES CX_LLM_PROVIDER_PROFILES(PROFILE_ID), PROFILE_VERSION INTEGER NOT NULL CHECK(PROFILE_VERSION>0), "
        "COORDINATOR_URL VARCHAR(1000) NOT NULL, BINDING_ID VARCHAR(128) NOT NULL, GROUP_ID VARCHAR(128) NOT NULL, "
        "POLICY_REVISION INTEGER NOT NULL CHECK(POLICY_REVISION>0), ORIGIN_ID VARCHAR(128) NOT NULL, INSTALLATION_KEY VARCHAR(128) NOT NULL, "
        "COORDINATOR_PROFILE_ID VARCHAR(128) NOT NULL, COORDINATOR_PROFILE_VERSION INTEGER NOT NULL CHECK(COORDINATOR_PROFILE_VERSION>0), "
        "CREDENTIAL_DIGEST VARCHAR(64) NOT NULL, STATUS VARCHAR(16) NOT NULL CHECK(STATUS IN ('ACTIVE','REVOKED')), "
        "VERSION INTEGER DEFAULT 1 NOT NULL CHECK(VERSION>0), REGISTERED_BY VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), "
        "IDEMPOTENCY_KEY VARCHAR(128) NOT NULL, REQUEST_DIGEST VARCHAR(64) NOT NULL, CREATED_AT_MS BIGINT_VALUE NOT NULL, "
        "UNIQUE(PROFILE_ID,PROFILE_VERSION), UNIQUE(REGISTERED_BY,IDEMPOTENCY_KEY))",
        "CREATE TABLE CX_MODEL_ORIGIN_RECEIPTS (ORIGIN_RECEIPT_ID VARCHAR(128) PRIMARY KEY, "
        "ROUTE_ID VARCHAR(128) NOT NULL REFERENCES CX_MODEL_COORD_ROUTES(ROUTE_ID), ROUTE_VERSION INTEGER NOT NULL CHECK(ROUTE_VERSION>0), "
        "ACTOR_ID VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), ORIGINAL_CREDENTIAL_DIGEST VARCHAR(64) NOT NULL, "
        "SOURCE_KIND VARCHAR(24) NOT NULL CHECK(SOURCE_KIND IN ('NATIVE','GATEWAY','PORTAL','CHANNEL','PROBE','RETROSPECTIVE','EVALUATION','EXTERNAL')), SOURCE_ID VARCHAR(128) NOT NULL, SOURCE_ATTEMPT_ID VARCHAR(128) NOT NULL, "
        "WORKER_KEY VARCHAR(128) NOT NULL, ORIGIN_FENCING_TOKEN INTEGER NOT NULL CHECK(ORIGIN_FENCING_TOKEN>0), "
        "ORIGIN_LEASE_UNTIL_MS BIGINT_VALUE NOT NULL, AUTHORITY_DIGEST VARCHAR(64) NOT NULL, "
        "PROFILE_ID VARCHAR(128) NOT NULL REFERENCES CX_LLM_PROVIDER_PROFILES(PROFILE_ID), PROFILE_VERSION INTEGER NOT NULL CHECK(PROFILE_VERSION>0), "
        "MODEL_ID VARCHAR(256) NOT NULL, PAYLOAD_DIGEST VARCHAR(64) NOT NULL, IDEMPOTENCY_KEY VARCHAR(128) NOT NULL, "
        "ENVELOPE_DIGEST VARCHAR(64) NOT NULL, COORDINATOR_REQUEST_ID VARCHAR(128), ADMISSION_ID VARCHAR(128), "
        "REMOTE_FENCING_TOKEN INTEGER, REMOTE_RESERVATION_VERSION INTEGER, AUTHORIZED_AT_MS BIGINT_VALUE, PROOF_EXPIRES_AT_MS BIGINT_VALUE, "
        "PROOF_DIGEST VARCHAR(64), STATUS VARCHAR(32) NOT NULL CHECK(STATUS IN ('PREPARED','RESERVED','DISPATCHING','COMPLETED','KNOWN_NO_SEND','UNKNOWN')), "
        "VERSION INTEGER DEFAULT 1 NOT NULL CHECK(VERSION>0), FINISH_CODE VARCHAR(128), CREATED_AT_MS BIGINT_VALUE NOT NULL, "
        "UNIQUE(ACTOR_ID,SOURCE_KIND,SOURCE_ID,SOURCE_ATTEMPT_ID), UNIQUE(ROUTE_ID,IDEMPOTENCY_KEY))",
        "CREATE TABLE CX_MODEL_COORD_REQUESTS (COORDINATOR_REQUEST_ID VARCHAR(128) PRIMARY KEY, "
        "BINDING_ID VARCHAR(128) NOT NULL REFERENCES CX_MODEL_COORD_BINDINGS(BINDING_ID), BINDING_VERSION INTEGER NOT NULL CHECK(BINDING_VERSION>0), "
        "ORIGIN_RECEIPT_ID VARCHAR(128) NOT NULL, INSTALLATION_KEY VARCHAR(128) NOT NULL, "
        "ACTOR_ID VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), "
        "CREDENTIAL_ID VARCHAR(128) NOT NULL REFERENCES CX_MODEL_GATEWAY_CREDENTIALS(CREDENTIAL_ID), CREDENTIAL_DIGEST VARCHAR(64) NOT NULL, "
        "ORIGIN_ACTOR_ID VARCHAR(128) NOT NULL, SOURCE_KIND VARCHAR(24) NOT NULL CHECK(SOURCE_KIND IN ('NATIVE','GATEWAY','PORTAL','CHANNEL','PROBE','RETROSPECTIVE','EVALUATION','EXTERNAL')), SOURCE_ID VARCHAR(128) NOT NULL, SOURCE_ATTEMPT_ID VARCHAR(128) NOT NULL, "
        "WORKER_KEY VARCHAR(128) NOT NULL, ORIGIN_FENCING_TOKEN INTEGER NOT NULL CHECK(ORIGIN_FENCING_TOKEN>0), "
        "ORIGIN_LEASE_UNTIL_MS BIGINT_VALUE NOT NULL, AUTHORITY_DIGEST VARCHAR(64) NOT NULL, "
        "ORIGIN_PROFILE_ID VARCHAR(128) NOT NULL, ORIGIN_PROFILE_VERSION INTEGER NOT NULL CHECK(ORIGIN_PROFILE_VERSION>0), "
        "PROFILE_ID VARCHAR(128) NOT NULL REFERENCES CX_LLM_PROVIDER_PROFILES(PROFILE_ID), PROFILE_VERSION INTEGER NOT NULL CHECK(PROFILE_VERSION>0), "
        "GROUP_ID VARCHAR(128) NOT NULL REFERENCES CX_MODEL_CAP_GROUPS(GROUP_ID), POLICY_REVISION INTEGER NOT NULL CHECK(POLICY_REVISION>0), "
        "MODEL_ID VARCHAR(256) NOT NULL, PAYLOAD_DIGEST VARCHAR(64) NOT NULL, IDEMPOTENCY_KEY VARCHAR(128) NOT NULL, ENVELOPE_DIGEST VARCHAR(64) NOT NULL, "
        "ADMISSION_ID VARCHAR(128) REFERENCES CX_MODEL_ADMISSIONS(ADMISSION_ID), PROOF_DIGEST VARCHAR(64), PROOF_EXPIRES_AT_MS BIGINT_VALUE, "
        "STATUS VARCHAR(32) NOT NULL CHECK(STATUS IN ('PREPARED','RESERVED','DISPATCHING','COMPLETED','KNOWN_NO_SEND','UNKNOWN')), "
        "VERSION INTEGER DEFAULT 1 NOT NULL CHECK(VERSION>0), FINISH_CODE VARCHAR(128), CREATED_AT_MS BIGINT_VALUE NOT NULL, "
        "UNIQUE(BINDING_ID,ORIGIN_RECEIPT_ID), UNIQUE(BINDING_ID,IDEMPOTENCY_KEY))",
        "CREATE TABLE CX_MODEL_ORIGIN_OBSERVATIONS (ORIGIN_RECEIPT_ID VARCHAR(128) PRIMARY KEY "
        "REFERENCES CX_MODEL_ORIGIN_RECEIPTS(ORIGIN_RECEIPT_ID), COORDINATOR_REQUEST_ID VARCHAR(128) NOT NULL, "
        "ADMISSION_ID VARCHAR(128) NOT NULL, REQUEST_COMPLETE VARCHAR(1) NOT NULL CHECK(REQUEST_COMPLETE IN ('Y','N')), "
        "RESULT_STATE VARCHAR(24) NOT NULL CHECK(RESULT_STATE IN ('COMPLETED','REJECTED','UNKNOWN')), "
        "FINISH_CODE VARCHAR(128) NOT NULL, USAGE_PROVENANCE VARCHAR(24) NOT NULL "
        "CHECK(USAGE_PROVENANCE IN ('PROVIDER_REPORTED','DERIVED_TOTAL','PARTIAL','INCOMPLETE')), "
        "PROMPT_TOKENS BIGINT_VALUE CHECK(PROMPT_TOKENS>=0), COMPLETION_TOKENS BIGINT_VALUE CHECK(COMPLETION_TOKENS>=0), "
        "TOTAL_TOKENS BIGINT_VALUE CHECK(TOTAL_TOKENS>=0), CACHED_TOKENS BIGINT_VALUE CHECK(CACHED_TOKENS>=0), "
        "CACHE_WRITE_TOKENS BIGINT_VALUE CHECK(CACHE_WRITE_TOKENS>=0), REASONING_TOKENS BIGINT_VALUE CHECK(REASONING_TOKENS>=0), "
        "QUEUE_MS BIGINT_VALUE CHECK(QUEUE_MS>=0), FIRST_CONTENT_MS BIGINT_VALUE CHECK(FIRST_CONTENT_MS>=0), "
        "PROVIDER_MS BIGINT_VALUE CHECK(PROVIDER_MS>=0), TOTAL_MS BIGINT_VALUE CHECK(TOTAL_MS>=0), "
        "OBSERVATION_DIGEST VARCHAR(64) NOT NULL, OBSERVED_AT_MS BIGINT_VALUE NOT NULL, "
        "CHECK((RESULT_STATE='UNKNOWN' AND REQUEST_COMPLETE='N') OR (RESULT_STATE IN ('COMPLETED','REJECTED') AND REQUEST_COMPLETE='Y')))",
        "CREATE TABLE CX_MODEL_ORIGIN_RESOLUTIONS (RESOLUTION_ID VARCHAR(128) PRIMARY KEY, ORIGIN_RECEIPT_ID VARCHAR(128) NOT NULL UNIQUE "
        "REFERENCES CX_MODEL_ORIGIN_RECEIPTS(ORIGIN_RECEIPT_ID), ROUTE_ID VARCHAR(128) NOT NULL REFERENCES CX_MODEL_COORD_ROUTES(ROUTE_ID), "
        "ROUTE_VERSION INTEGER NOT NULL CHECK(ROUTE_VERSION>0), COORDINATOR_REQUEST_ID VARCHAR(128) NOT NULL, ADMISSION_ID VARCHAR(128) NOT NULL, "
        "ADMISSION_VERSION INTEGER NOT NULL CHECK(ADMISSION_VERSION>0), ATTEMPT_ID VARCHAR(128), FENCING_TOKEN INTEGER NOT NULL CHECK(FENCING_TOKEN>=0), "
        "CENTRAL_STATUS VARCHAR(32) NOT NULL CHECK(CENTRAL_STATUS IN ('PREPARED','RESERVED','DISPATCHING','COMPLETED','KNOWN_NO_SEND','UNKNOWN')), "
        "ADMISSION_STATUS VARCHAR(24) NOT NULL CHECK(ADMISSION_STATUS IN ('COMPLETED','CANCELLED','EXPIRED','REJECTED')), "
        "OBSERVATION_METHOD VARCHAR(40) NOT NULL CHECK(OBSERVATION_METHOD='REGISTERED_COORDINATOR_GET'), "
        "RESOLUTION_KIND VARCHAR(32) NOT NULL CHECK(RESOLUTION_KIND IN ('KNOWN_NO_SEND','TRANSPORT_TERMINATED')), "
        "EVIDENCE_ID VARCHAR(128) NOT NULL, EVIDENCE_KIND VARCHAR(32) NOT NULL "
        "CHECK(EVIDENCE_KIND IN ('NO_SEND_STATE','COMPLETE_RESPONSE','REMOTE_TERMINATED','LOCAL_LIFECYCLE','OPERATOR_CONFIRMATION')), "
        "EVIDENCE_DIGEST VARCHAR(64) NOT NULL, EVIDENCE_AT_MS BIGINT_VALUE NOT NULL, REQUEST_COMPLETE VARCHAR(1) NOT NULL CHECK(REQUEST_COMPLETE IN ('Y','N')), "
        "PEER_RECEIPT_DIGEST VARCHAR(64) NOT NULL, REQUESTED_BY VARCHAR(128) NOT NULL REFERENCES CX_PRINCIPALS(PRINCIPAL_ID), "
        "IDEMPOTENCY_KEY VARCHAR(128) NOT NULL, REQUEST_DIGEST VARCHAR(64) NOT NULL, REASON VARCHAR(1000) NOT NULL, OBSERVED_AT_MS BIGINT_VALUE NOT NULL, "
        "UNIQUE(REQUESTED_BY,IDEMPOTENCY_KEY), CHECK((RESOLUTION_KIND='KNOWN_NO_SEND' AND ATTEMPT_ID IS NULL) "
        "OR (RESOLUTION_KIND='TRANSPORT_TERMINATED' AND ATTEMPT_ID IS NOT NULL AND FENCING_TOKEN>0)))",
    ]
    return [statement.replace('BIGINT_VALUE',integer) for statement in statements]
